#!/usr/bin/env ruby
require'json';require'digest';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);archive=File.join(client,'development/archived-game-folders');active=File.join(client,'assets');index=Hash.new{|h,k|h[k]=[]};Dir.glob(File.join(active,'**/*')).select{|p|File.file?(p)&&!p.end_with?('.meta')}.each{|p|index[Digest::SHA256.file(p).hexdigest]<<p.delete_prefix(client+'/')};rows=Dir.glob(File.join(archive,'**/*')).select{|p|File.file?(p)&&!p.end_with?('.meta')}.sort.map{|p|sha=Digest::SHA256.file(p).hexdigest;[p.delete_prefix(client+'/'),File.extname(p),File.size(p),sha,index[sha].join(',')]};tsv=File.join(root,'docs/generated/carch03-game-archive-inventory.tsv');FileUtils.mkdir_p(File.dirname(tsv));File.write(tsv,"archivePath\textension\tbytes\tsha256\tactiveExactMatches\n"+rows.map{|r|r.join("\t")}.join("\n")+"\n");unmigrated=rows.count{|r|r[4].empty?};report={schemaVersion:1,archiveFiles:rows.length,exactlyMigrated:rows.length-unmigrated,unmigrated:unmigrated,inventory:'docs/generated/carch03-game-archive-inventory.tsv',inventorySha256:Digest::SHA256.file(tsv).hexdigest,verdict:unmigrated.zero? ? 'passed':'blocked-unmigrated-archive-assets'};File.write(File.join(root,'docs/generated/carch03-game-archive-inventory.json'),JSON.pretty_generate(report)+"\n");puts "CARCH03 AUDITED: #{rows.length} files, #{unmigrated} without exact active replacement"
